def solveSudoku(sudoku, i=0, j=0):
	i, j = findNextCellToFill(sudoku)
	if i == -1:
		return True
	for e in range(1, 10):
		if isValid(sudoku, i, j, e):
			sudoku[i][j] = e
			if solveSudoku(sudoku, i, j):
				return True
			sudoku[i][j] = 0
	return False

def bubbleSort(arr):
	n = len(arr)
	for i in range(n-1):
		for j in range(0, n-i-1):
			if arr[j] > arr[j + 1]:
				arr[j], arr[j + 1] = arr[j + 1], arr[j]

def search(arr, n, x):
