def addBegin(self, data):
	if (self.last == None):
		return self.addToEmpty(data)
	temp = Node(data)
	temp.next = self.last.next
	self.last.next = temp
	return self.last

def addEnd(self, data):
	if (self.last == None):
		return self.addToEmpty(data)
	temp = Node(data)
	temp.next = self.last.next
	self.last.next = temp
	self.last = temp
	return self.last

def chain(*iterables):
	# chain('ABC', 'DEF') --> A B C D E F
	for it in iterables:
		for element in it:
			yield element

